export const homePage = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Emika Addon</title>
<style>
:root{color-scheme:dark;--bg:#110d16;--panel:#211824;--panel2:#302235;--line:#51354d;--text:#fff8fb;--muted:#c4aebc;--accent:#ffb4d2;--accent2:#ff6f9f;--danger:#ff9da9;--info:#b8b5ff;--mascot:url("data:image/jpeg;base64,")}
*{box-sizing:border-box}html,body{margin:0;background:radial-gradient(circle at 12% 0,#382238 0,#110d16 48%,#08060b 100%);color:var(--text);font:16px Inter,Arial,sans-serif;min-height:100%}body{padding:22px}main{max-width:1120px;margin:0 auto}.shell{background:rgba(25,17,29,.88);border:1px solid #6b405e;border-radius:24px;box-shadow:0 24px 80px #000b;overflow:hidden;backdrop-filter:blur(14px)}
header{position:relative;isolation:isolate;min-height:174px;padding:30px 32px 26px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;gap:18px;overflow:hidden;background:linear-gradient(90deg,rgba(17,10,18,.98) 0%,rgba(27,15,28,.91) 45%,rgba(27,15,28,.45) 100%)}header:after{content:"";position:absolute;z-index:-1;inset:0 0 0 38%;background-image:linear-gradient(90deg,#1b0f1c 0%,rgba(27,15,28,.7) 20%,rgba(27,15,28,.05) 70%),var(--mascot);background-size:cover;background-position:center 24%;opacity:.74}.brand{display:flex;align-items:center;gap:16px;position:relative}.logo{width:64px;height:64px;border-radius:20px;background-image:linear-gradient(145deg,rgba(255,180,210,.15),rgba(17,8,19,.15)),var(--mascot);background-size:cover;background-position:70% 23%;border:2px solid rgba(255,180,210,.75);box-shadow:0 0 0 5px rgba(255,180,210,.1),0 12px 30px #0009}.eyebrow{color:var(--accent);font-size:11px;font-weight:900;letter-spacing:2px;text-transform:uppercase}.brand h1{margin:3px 0 0;font-size:30px;letter-spacing:.3px;text-shadow:0 3px 24px #000}.sub{color:#e2cbd7;font-size:13px;margin:6px 0 0}.health{display:flex;align-items:center;gap:8px;color:#ead8e2;font-size:12px;text-align:right;position:relative}.dot{width:9px;height:9px;border-radius:50%;background:#8e7182}.dot.ok{background:#8ff0bc;box-shadow:0 0 15px #8ff0bc}.dot.bad{background:var(--danger)}
.content{padding:28px 32px;background:linear-gradient(180deg,rgba(34,22,38,.55),rgba(17,11,21,.25))}.toolbar{display:flex;gap:10px;align-items:center;margin-bottom:14px}.searchbox{display:flex;gap:10px;flex:1}.input,select,button{font:inherit;border-radius:10px;border:1px solid var(--line);min-height:44px}.input{background:rgba(12,8,15,.76);color:var(--text);padding:11px 14px;flex:1;min-width:0;border-color:#68445f}select{background:rgba(12,8,15,.76);color:var(--text);padding:10px 12px;min-width:145px;border-color:#68445f}button{background:linear-gradient(135deg,var(--accent),#ff86b5);color:#2a1020;border:0;font-weight:900;padding:10px 17px;cursor:pointer;box-shadow:0 8px 22px #ff6f9f2b}button.secondary,.icon{background:rgba(48,34,53,.86);border:1px solid #714d68;color:var(--text);box-shadow:none}button:disabled{opacity:.55;cursor:wait}button:focus,.input:focus,select:focus{outline:3px solid var(--info);outline-offset:2px}.hint{color:var(--muted);font-size:12px;margin:0 0 16px}.notice{display:none;border-radius:10px;padding:12px 14px;margin:0 0 16px;font-size:13px;line-height:1.45}.notice.show{display:block}.notice.error{background:#3b1e25;color:#ffd4d4;border:1px solid #81414d}.notice.info{background:#142b42;color:#d5eaff;border:1px solid #2e6598}.notice button{min-height:32px;padding:5px 10px;margin-left:8px;font-size:12px}
#status{min-height:24px;color:var(--muted);margin:10px 0 14px}.results{display:grid;gap:9px}.empty{color:var(--muted);padding:28px 8px;text-align:center;border:1px dashed var(--line);border-radius:12px}.card{display:flex;align-items:center;gap:14px;padding:13px;background:linear-gradient(105deg,rgba(45,27,45,.92),rgba(22,15,27,.88));border:1px solid #56374f;border-radius:16px;transition:transform .18s ease,border-color .18s ease,box-shadow .18s ease}.card:hover{transform:translateY(-2px);border-color:#ad668c;box-shadow:0 12px 30px #0006}.cover{width:62px;height:62px;background:#3b2638;object-fit:cover;border-radius:9px;flex:none}.meta{flex:1;min-width:0}.title{font-size:17px;font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.artist{color:var(--muted);margin-top:4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.tag{display:inline-block;color:var(--accent);font-size:11px;font-weight:800;letter-spacing:.5px;margin-top:7px;padding:3px 7px;background:#273216;border-radius:5px}.actions{display:flex;gap:6px;align-items:center}.play,.small{min-width:70px}.small{min-height:34px;padding:5px 9px;font-size:12px}.icon{min-width:36px;padding:5px 8px;font-size:18px}.active{color:var(--accent)!important}
.section-title{display:flex;align-items:center;justify-content:space-between;margin:19px 0 9px;font-weight:800;font-size:14px}.section-title span{color:var(--muted);font-size:12px;font-weight:400}.history,.favorites,.queue{display:flex;gap:7px;flex-wrap:wrap;margin:0 0 14px}.history button,.favorites button,.queue button{min-height:30px;padding:4px 9px;font-size:12px;background:transparent;color:var(--muted);border:1px solid var(--line)}.queue{display:grid;gap:6px}.queue-item{width:100%;display:flex;justify-content:space-between;align-items:center;text-align:left}.queue-item b{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin-right:8px}.queue-item span{font-size:11px;color:var(--muted);white-space:nowrap}
.player{position:sticky;bottom:0;margin-top:24px;padding:18px;background:linear-gradient(135deg,rgba(55,29,52,.96),rgba(24,15,29,.96));border:1px solid #754968;border-radius:17px;box-shadow:0 -12px 35px #0005}.now{font-weight:800;margin-bottom:9px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.player small{color:var(--muted);display:block;margin-bottom:9px}audio{width:100%;height:38px}.player-actions{display:flex;gap:7px;margin-top:10px}.player-actions button{min-height:34px;padding:5px 10px;font-size:12px}.footer{padding:15px 28px;border-top:1px solid var(--line);display:flex;justify-content:space-between;gap:12px;color:var(--muted);font-size:11px}
@media(max-width:700px){body{padding:8px}header,.content,.footer{padding-left:16px;padding-right:16px}header{align-items:flex-start;flex-direction:column}.health{text-align:left}.toolbar{align-items:stretch;flex-direction:column}.searchbox{flex-direction:column}select,.searchbox button{width:100%}.card{gap:9px;align-items:flex-start}.cover{width:52px;height:52px}.title{font-size:15px}.actions{flex-direction:column}.play{min-width:65px;padding:7px}.footer{flex-direction:column}}
</style>
</head>
<body>
<main class="shell">
<header><div class="brand"><div class="logo" role="img" aria-label="Emika mascot"></div><div><div class="eyebrow">Music addon</div><h1>Emika Addon</h1><p class="sub">Lossless and Hi-Res music search</p></div></div><div class="health"><span id="healthDot" class="dot"></span><span id="healthText">Checking server...</span><button id="healthButton" class="small secondary" type="button">STATUS</button></div></header>
<section class="content">
<div class="toolbar"><form id="searchForm" class="searchbox"><input id="query" class="input" type="search" placeholder="Search artist, album or track" autocomplete="off" aria-label="Search music"><select id="quality" title="Audio quality" aria-label="Audio quality"></select><button id="searchButton" type="submit">SEARCH</button></form><button id="refreshButton" class="secondary" type="button" title="Reload manifest settings">REFRESH</button></div>
<p id="qualityHint" class="hint">Loading available quality tiers...</p><div class="section-title"><span>Recent searches</span><button id="clearHistory" class="small secondary" type="button">CLEAR</button></div><div id="history" class="history"></div><div class="section-title"><span>Favorites</span><span id="favoriteCount">0 saved</span></div><div id="favorites" class="favorites"></div><div id="notice" class="notice" role="status"></div><div id="status">Preparing Emika Addon...</div><div id="results" class="results"><div class="empty">Search for music to begin.</div></div>
<div class="section-title"><span>Queue</span><button id="clearQueue" class="small secondary" type="button">CLEAR QUEUE</button></div><div id="queue" class="queue"><div class="empty">Queue is empty.</div></div>
<section class="player"><div id="nowPlaying" class="now">Nothing playing</div><small id="nowMeta">Select a result to start playback.</small><audio id="audio" controls preload="none"></audio><div class="player-actions"><button id="previousButton" class="secondary" type="button">PREVIOUS</button><button id="nextButton" class="secondary" type="button">NEXT</button><a id="downloadButton" class="small secondary" hidden download>DOWNLOAD</a></div></section>
</section><footer><span id="version">Emika Addon</span><span>Settings follow server manifest</span></footer>
</main>
<script>
(function(){
  var tracks=[],queue=[],favorites=[],manifest=null,currentTrack=null,queueIndex=-1;
  var historyKey='emika-addon-search-history-v1',favoritesKey='emika-addon-favorites-v1',queueKey='emika-addon-queue-v1';
  function el(id){return document.getElementById(id);}
  function esc(value){return String(value==null?'':value).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');}
  function request(url,done){var x=new XMLHttpRequest();x.onreadystatechange=function(){if(x.readyState!==4)return;var data=null;try{data=x.responseText?JSON.parse(x.responseText):null;}catch(e){}if(x.status>=200&&x.status<300)done(null,data,x.status);else{var message=data&&typeof data.error==='string'?data.error:null;done(new Error(message||('HTTP '+x.status)),data,x.status);}};x.onerror=function(){done(new Error('Network error'),null,0);};x.open('GET',url,true);x.send();}
  function showNotice(kind,message){var n=el('notice');n.className='notice '+kind+' show';n.textContent=message;}
  function clearNotice(){var n=el('notice');n.className='notice';n.textContent='';}
  function friendlyError(error,status){var message=error&&error.message?error.message:'';if(/quality tier HI_RES is disabled/i.test(message))return 'Hi-Res is disabled on this server. Choose Lossless from the quality menu.';if(/quality tier LOW is disabled/i.test(message))return 'Low quality is disabled on this server. Choose another quality.';if(status===429)return 'Too many requests. Please wait a moment and try again.';if(status===403)return 'This request is not allowed by the addon policy.';if(status>=500)return 'The music source is temporarily unavailable. Please try again.';return message||'Request could not be completed.';}
  function save(key,value){try{localStorage.setItem(key,JSON.stringify(value));}catch(e){}}
  function load(key,fallback){try{var value=JSON.parse(localStorage.getItem(key)||'null');return value==null?fallback:value;}catch(e){return fallback;}}
  function optionsFromManifest(){var select=el('quality');select.innerHTML='';var options=manifest&&manifest.settings&&manifest.settings[0]&&manifest.settings[0].options;options=Array.isArray(options)?options:[];if(!options.length)options=[{label:'Lossless',value:'lossless'}];for(var i=0;i<options.length;i++){var o=options[i];if(!o||typeof o.value!=='string')continue;var option=document.createElement('option');option.value=o.value;option.textContent=o.label||o.value;select.appendChild(option);}var preferred=manifest&&manifest.settings&&manifest.settings[0]&&manifest.settings[0].default;if(preferred){for(var j=0;j<select.options.length;j++){if(select.options[j].value===preferred){select.selectedIndex=j;break;}}}el('qualityHint').textContent='Available: '+Array.prototype.map.call(select.options,function(o){return o.text;}).join(' · ');}
  function loadManifest(){el('refreshButton').disabled=true;request('/manifest.json?ui='+Date.now(),function(error,data){el('refreshButton').disabled=false;if(error||!data){showNotice('error','Could not load addon settings. Lossless is available as a safe fallback.');manifest=null;optionsFromManifest();return;}manifest=data;optionsFromManifest();el('version').textContent='Emika Addon '+(data.version||'');el('healthDot').className='dot ok';el('healthText').textContent='Server ready';clearNotice();updateDownloadVisibility();});}
  function setHealth(ok,text){el('healthDot').className='dot '+(ok?'ok':'bad');el('healthText').textContent=text;}
  function loadHistory(){var values=load(historyKey,[]);if(!Array.isArray(values))values=[];var box=el('history');box.innerHTML='';for(var i=0;i<Math.min(values.length,6);i++){var b=document.createElement('button');b.type='button';b.textContent=values[i];b.onclick=(function(v){return function(){el('query').value=v;doSearch();};})(values[i]);box.appendChild(b);}}
  function saveHistory(value){var values=load(historyKey,[]);if(!Array.isArray(values))values=[];values=[value].concat(values.filter(function(v){return v!==value;})).slice(0,6);save(historyKey,values);loadHistory();}
  function metadata(t){var bits=[];if(t.format)bits.push(String(t.format).toUpperCase());if(t.audioQuality)bits.push(String(t.audioQuality).replace(/_/g,' '));if(t.bitDepth)bits.push(t.bitDepth+'-bit');if(t.sampleRate)bits.push((Number(t.sampleRate)/1000)+' kHz');return bits.join(' · ')||'Audio';}
  function isFavorite(t){return favorites.some(function(f){return f.id===t.id;});}
  function toggleFavorite(t){if(isFavorite(t))favorites=favorites.filter(function(f){return f.id!==t.id;});else favorites.unshift({id:t.id,title:t.title,artist:t.artist,album:t.album,artworkURL:t.artworkURL,format:t.format,audioQuality:t.audioQuality,sampleRate:t.sampleRate,bitDepth:t.bitDepth});favorites=favorites.slice(0,50);save(favoritesKey,favorites);renderFavorites();render();}
  function renderFavorites(){var box=el('favorites');el('favoriteCount').textContent=favorites.length+' saved';box.innerHTML='';if(!favorites.length){box.innerHTML='<span class="hint">No favorites yet.</span>';return;}favorites.slice(0,8).forEach(function(t){var b=document.createElement('button');b.type='button';b.textContent=t.title||'Track';b.title=t.artist||'';b.onclick=function(){playTrack(t);};box.appendChild(b);});}
  function addToQueue(t){queue.push(t);save(queueKey,queue);renderQueue();if(!currentTrack)playQueueAt(0);}
  function removeFromQueue(i){queue.splice(i,1);if(queueIndex===i)queueIndex=-1;else if(queueIndex>i)queueIndex--;save(queueKey,queue);renderQueue();}
  function renderQueue(){var box=el('queue');box.innerHTML='';if(!queue.length){box.innerHTML='<div class="empty">Queue is empty.</div>';return;}queue.forEach(function(t,i){var b=document.createElement('button');b.type='button';b.className='queue-item';b.innerHTML='<b>'+esc(t.title||'Track')+'</b><span>'+esc(t.artist||'')+' · REMOVE</span>';b.onclick=function(e){if(e.target&&e.target.tagName==='SPAN'){removeFromQueue(i);}else{playQueueAt(i);}};box.appendChild(b);});}
  function render(){var box=el('results');if(!tracks.length){box.innerHTML='<div class="empty">No tracks found.</div>';return;}var html='';for(var i=0;i<tracks.length;i++){var t=tracks[i];html+='<article class="card"><img class="cover" src="'+esc(t.artworkURL||'')+'" alt=""><div class="meta"><div class="title">'+esc(t.title)+'</div><div class="artist">'+esc(t.artist||t.album||'Unknown artist')+'</div><div class="tag">'+esc(metadata(t))+'</div></div><div class="actions"><button class="icon '+(isFavorite(t)?'active':'')+'" type="button" data-fav="'+i+'" title="Favorite">★</button><button class="small secondary" type="button" data-queue="'+i+'">QUEUE</button><button class="play" type="button" data-play="'+i+'">PLAY</button></div></article>';}box.innerHTML=html;Array.prototype.forEach.call(box.querySelectorAll('[data-play]'),function(b){b.onclick=function(){playTrack(tracks[Number(b.getAttribute('data-play'))]);};});Array.prototype.forEach.call(box.querySelectorAll('[data-queue]'),function(b){b.onclick=function(){addToQueue(tracks[Number(b.getAttribute('data-queue'))]);};});Array.prototype.forEach.call(box.querySelectorAll('[data-fav]'),function(b){b.onclick=function(){toggleFavorite(tracks[Number(b.getAttribute('data-fav'))]);};});}
  function doSearch(){var q=el('query').value.replace(/^\\s+|\\s+$/g,'');if(!q){showNotice('info','Enter an artist, album or track to search.');return false;}var quality=el('quality').value||'lossless';el('searchButton').disabled=true;el('status').textContent='Searching...';el('results').innerHTML='';clearNotice();saveHistory(q);request('/search?q='+encodeURIComponent(q)+'&quality='+encodeURIComponent(quality)+'&atmos=auto',function(error,data,status){el('searchButton').disabled=false;if(error||!data){setHealth(false,'Search unavailable');showNotice('error',friendlyError(error,status));el('status').textContent='Search request failed';return;}setHealth(true,'Server ready');tracks=Array.isArray(data.tracks)?data.tracks:[];el('status').textContent=tracks.length+' result'+(tracks.length===1?'':'s')+' found'+(data.stale?' (cached fallback)':'');render();});return false;}
  function safeFilePart(value,fallback){var text=String(value||fallback||'');try{text=text.normalize('NFC');}catch(e){}text=text.replace(/[\\\\/:*?"<>|\\x00-\\x1f\\x7f-\\x9f\\u2028\\u2029\\u200b-\\u200f\\u202a-\\u202e\\u2060-\\u2064\\u2066-\\u206f\\ufeff]/g,' ').replace(/[. ]+$/g,'').replace(/\\s+/g,' ').trim();if(/^(con|prn|aux|nul|com[1-9]|lpt[1-9])$/i.test(text))text='_'+text;return text||fallback||'Unknown';}
  function utf8Length(value){return new TextEncoder().encode(value).length;}
  function trimUtf8(value,maxBytes){var chars=Array.from(value);while(chars.length&&utf8Length(chars.join(''))>maxBytes)chars.pop();return chars.join('').trim();}
  function downloadFilename(track,stream){var artist=safeFilePart(track.artist||track.album,'Unknown Artist');var title=safeFilePart(track.title,'Unknown Song');var format=String((stream&&stream.format)||'flac').toLowerCase().replace(/^audio\\//,'').replace(/[^a-z0-9.+-]/g,'').slice(0,12)||'flac';var extension='.'+format;var maxBytes=240;var separator=' - ';var partLimit=Math.max(16,Math.floor((maxBytes-utf8Length(separator+extension))/2));artist=trimUtf8(artist,partLimit);title=trimUtf8(title,partLimit);while(utf8Length(artist+separator+title+extension)>maxBytes&&title.length)title=Array.from(title).slice(0,-1).join('').trim();while(utf8Length(artist+separator+title+extension)>maxBytes&&artist.length)artist=Array.from(artist).slice(0,-1).join('').trim();return artist+separator+title+extension;}
  function playTrack(t){if(!t)return;currentTrack=t;var quality=el('quality').value||'lossless';var requestedFilename=downloadFilename(t,{format:'flac'});el('nowPlaying').textContent='Loading: '+(t.title||'track');el('nowMeta').textContent='Resolving '+quality+' stream...';request('/stream/'+encodeURIComponent(t.id)+'?quality='+encodeURIComponent(quality)+'&atmos=auto&filename='+encodeURIComponent(requestedFilename),function(error,data,status){if(error||!data||!data.url){el('nowPlaying').textContent='Playback unavailable';el('nowMeta').textContent=friendlyError(error,status);showNotice('error',friendlyError(error,status));return;}clearNotice();el('nowPlaying').textContent='Playing: '+(t.title||'track')+(t.artist?' — '+t.artist:'');el('nowMeta').textContent=metadata(data);var audio=el('audio');audio.src=data.url;audio.load();audio.play().catch(function(){el('nowMeta').textContent+=' · Press play to start';});var download=el('downloadButton');var filename=downloadFilename(t,data);download.href='/download/'+encodeURIComponent(t.id)+'?quality='+encodeURIComponent(quality)+'&atmos=auto&filename='+encodeURIComponent(filename);download.download=filename;download.title='Download '+filename;download.hidden=!(manifest&&manifest.allowDownloads===1);});}
  function playQueueAt(i){if(i<0||i>=queue.length)return;queueIndex=i;playTrack(queue[i]);}
  function nextTrack(){if(queueIndex>=0&&queueIndex+1<queue.length)playQueueAt(queueIndex+1);else el('nowMeta').textContent='Queue finished';}
  function previousTrack(){if(queueIndex>0)playQueueAt(queueIndex-1);else if(currentTrack)playTrack(currentTrack);}
  function updateDownloadVisibility(){el('downloadButton').hidden=!(manifest&&manifest.allowDownloads===1);}
  function checkHealth(){el('healthButton').disabled=true;request('/health/sources',function(error,data){el('healthButton').disabled=false;if(error||!data){setHealth(false,'Health check failed');showNotice('error',friendlyError(error,0));return;}setHealth(data.overallStatus!=='outage',data.overallStatus||'Health checked');showNotice('info','Sources: '+(data.healthySources||0)+' healthy / '+(data.enabledSources||0)+' enabled');});}
  el('searchForm').onsubmit=function(){return doSearch();};el('refreshButton').onclick=loadManifest;el('healthButton').onclick=checkHealth;el('clearHistory').onclick=function(){save(historyKey,[]);loadHistory();};el('clearQueue').onclick=function(){queue=[];queueIndex=-1;save(queueKey,queue);renderQueue();};el('nextButton').onclick=nextTrack;el('previousButton').onclick=previousTrack;el('audio').onended=nextTrack;
  favorites=load(favoritesKey,[]);queue=load(queueKey,[]);if(!Array.isArray(favorites))favorites=[];if(!Array.isArray(queue))queue=[];loadHistory();renderFavorites();renderQueue();loadManifest();request('/health',function(error){if(error)setHealth(false,'Server unavailable');else setHealth(true,'Server ready');});
})();
</script>
</body>
</html>`;
